{"term":"sborra","lang":"it","script":"latin","romanization":null,"category":"fluids_states","subcategory":"semen","concept":"semen","is_novel_concept":false,"register":"slang_crude","crude":92,"technical":3,"recognition_pct_current":97,"recognition_pct_peak":97,"peak_year":null,"regional":null,"definition":"Extremely crude and very widespread Italian slang for semen; one of the most common vulgar terms in Italian sexual vocabulary.","english_term":"cum","english_translation_quality":"direct","notes":"Also used as a verb ('sborrare') meaning to ejaculate. Among the most ubiquitous crude sexual terms in Italian, comparable to English 'cum' in frequency and register."}
{"term":"fluido vaginale","lang":"it","script":"latin","romanization":null,"category":"fluids_states","subcategory":"vaginal_fluid","concept":"vaginal_discharge","is_novel_concept":false,"register":"clinical","crude":2,"technical":88,"recognition_pct_current":60,"recognition_pct_peak":60,"peak_year":null,"regional":null,"definition":"Clinical Italian term for vaginal fluid; the secretions produced by the cervix and vaginal walls, encompassing both normal arousal lubrication and pathological discharge.","english_term":"vaginal fluid","english_translation_quality":"direct","notes":""}
